// The snapshot date (Manila), the key that stops a second run in the same week adding rows.
const date = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Manila', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const d = new Date(date + 'T00:00:00Z');
const monday = new Date(d.getTime() - ((d.getUTCDay() + 6) % 7) * 86400000).toISOString().slice(0, 10);
return [{ json: { date, weekOf: monday } }];

const PORTAL = '247728856';
const PIPELINE = '2630364862';
const STAGE = { NEW: '4456833770', CONTACTED: '4456833771', CALL: '4456833772', PROPOSAL: '4456833773' };
const STAGE_NAME = { '4456833770': 'New lead', '4456833771': 'Contacted', '4456833772': 'Call booked', '4456833773': 'Proposal sent', '4456833775': 'Closed Won', '4456833776': 'Closed Lost' };
const DAY = 24 * 3600 * 1000;
const dealUrl = (id) => 'https://app-na2.hubspot.com/contacts/' + PORTAL + '/record/0-3/' + id;
const entered = (p) => Date.parse(p.hs_v2_date_entered_current_stage || p.createdate);

// Skip if this week is already in the tab; otherwise one row per open deal.
const { date, weekOf } = $('Snapshot date').first().json;
const existing = ($('Read snapshot dates').first().json.values ?? []).map((r) => String(r[0] ?? ''));
const weekStart = Date.parse(weekOf + 'T00:00:00Z');
if (existing.some((v) => /^\d{4}-\d{2}-\d{2}$/.test(v) && Date.parse(v + 'T00:00:00Z') >= weekStart)) return [];
const owners = {};
for (const o of $('List owners').first().json.results ?? []) owners[String(o.id)] = [o.firstName, o.lastName].filter(Boolean).join(' ') || o.email;
const now = Date.now();
const rows = ($('Find open deals').first().json.results ?? []).map((d) => {
  const p = d.properties;
  const since = entered(p);
  return [
    date,
    String(d.id),
    p.dealname ?? '',
    STAGE_NAME[p.dealstage] ?? p.dealstage,
    p.hubspot_owner_id ? owners[String(p.hubspot_owner_id)] ?? String(p.hubspot_owner_id) : 'Unclaimed',
    p.tca_lead_score ?? '',
    p.tca_lead_bucket ?? '',
    Number.isNaN(since) ? '' : Math.floor((now - since) / DAY),
    String(p.createdate ?? '').slice(0, 10),
  ];
});
if (!rows.length) return [];
return [{ json: { values: rows } }];
